options.afterRender:
(function () {
  context.element.addEventListener('click', function (event) {
    var card = event.target.closest('.clickable-poke-card');
    if (card) {
      event.preventDefault();
      var pokemonName = card.getAttribute('data-pokemon');
      if (pokemonName) {
        context.grafana.locationService.partial({ 'var-Pokemon': pokemonName });
      }
    }
  });
})();

