*, *::before, *::after { box-sizing: border-box !important; }

/* Contenedor Principal Estilo Dispositivo Médico/Científico Fluido y Sin Bordes Pesados */
.pokedex-spectrometer {
  background: radial-gradient(circle at 50% 50%, #2d323c 10%, #15171c 90%) !important;

  /* SE ELIMINAN LOS BORDES Y OUTLINES DE KPI */
  border: none !important;
  outline: none !important;

  border-radius: 12px !important;
  padding: 22px !important; /* Más aire interno para albergar fuentes grandes */
  box-shadow: 0 12px 32px rgba(0, 0, 0, 0.6) !important;
  width: 100% !important;
  position: relative !important;
  overflow: hidden !important;
  font-family: 'Courier New', monospace !important;
}

/* ==========================================================================
   AQUÍ ESTÁ: La Pokébola flotando por encima con z-index y gradiente corregidos
   ========================================================================== */
.pokedex-spectrometer::after {
  content: "" !important;
  position: absolute !important;
  right: -25px !important;
  bottom: -25px !important;
  width: 130px !important; /* Escalado perfecto para las fuentes grandes */
  height: 130px !important;

  background: radial-gradient(circle, transparent 18%, #15171c 18.5%, #15171c 26%, transparent 26.5%),
              linear-gradient(to bottom, rgba(239, 68, 68, 0.15) 50%, rgba(255, 255, 255, 0.08) 50.5%) !important;

  border: 2px solid rgba(255, 255, 255, 0.08) !important;
  border-radius: 50% !important;
  opacity: 0.8 !important;
  z-index: 3 !important; /* Pasa al frente por encima de las barras gráficas */
  pointer-events: none !important;
}

/* Cabecera Técnica */
.spec-header {
  text-align: center !important;
  font-size: 14px !important; /* Letra grande incrementada */
  font-weight: 900 !important;
  color: #ffcb05 !important;
  letter-spacing: 1.5px !important;
  margin-bottom: 18px !important;
  border-bottom: 2px solid #ffcb05 !important;
  padding-bottom: 8px !important;
  z-index: 2 !important;
  position: relative !important;
  text-shadow: 1.5px 1.5px 0px #111 !important;
}

/* Indicadores de los ejes */
.spec-axis-label {
  display: flex !important;
  justify-content: space-between !important;
  font-size: 12px !important; /* Letra grande incrementada */
  font-weight: 900 !important;
  margin-bottom: 16px !important;
  padding: 0 10px !important;
