/* Filas del Espectrómetro */
.spec-grid {
  display: flex !important;
  flex-direction: column !important;
  gap: 12px !important;
  z-index: 2 !important;
  position: relative !important;
}
.spec-row {
  display: flex !important;
  align-items: center !important;
  height: 32px !important; /* Ligeramente más alto para balancear el texto */
  position: relative !important;
}

/* Alineaciones Simétricas */
.spec-side {
  flex: 1 !important;
  display: flex !important;
  align-items: center !important;
  gap: 12px !important;
}
.spec-left { justify-content: flex-end !important; }
.spec-right { justify-content: flex-start !important; }

/* Nodo del Centro */
.spec-center {
  width: 120px !important; /* Más ancho para que el texto grande respire */
  text-align: center !important;
  flex-shrink: 0 !important;
  z-index: 4 !important; /* Por encima del reflejo de la Pokébola */
}

/* Píldoras de Tipo estilizadas */
.spec-pill {
  display: inline-block !important;
