.res-wrapper { direction: rtl !important; } 

/* Barras animadas con brillos neón */
.spec-bar {
  height: 100% !important;
  border-radius: 9999px !important;
  transition: width 0.4s ease-out !important;
}
.bar-vuln-fill {
