(function () {
  context.element.addEventListener('click', function (event) {
    var card = event.target.closest('.pokemon-card');
    if (card) {
      var name = card.getAttribute('data-pokemon');
      if (name) {
        context.grafana.locationService.partial({ 'var-Pokemon_counter': name });
      }
    }
  });
})();

