options.afterRender:
(function () {
  var s = context.panelData && context.panelData.series;
  if (!s || !s.length) return;

  function vl(fr, nm) {
    if (!fr || !fr.fields) return [];
    var f = fr.fields.find(function (x) { return x.name === nm; });
    if (!f || f.values == null) return [];
    var v = f.values;
    if (Array.isArray(v)) return v;
    var a = [], n = v.length || 0;
    for (var i = 0; i < n; i++) a.push(v.get ? v.get(i) : v[i]);
    return a;
  }

  var sf = s[0];
  var atk = Number(vl(sf, 'ataque_base')[0]) || 0;
  var def = Number(vl(sf, 'defensa_base')[0]) || 0;
  var sta = Number(vl(sf, 'stamina_base')[0]) || 0;
  var attacksRaw = vl(sf, 'attacks')[0];
  var attacks = [];

  try {
    attacks = typeof attacksRaw === 'string' ? JSON.parse(attacksRaw) : (attacksRaw || []);
  } catch (e) {
    console.error("Error parseando ataques:", e);
  }

  /* --- Pills --- */
  var pills = context.element.querySelector('.sp-pills');
  if (pills) {
    pills.innerHTML =
      '<div class="sp-pill atk-p"><span>ATK</span> <span>' + atk + '</span></div>' +
      '<div class="sp-pill def-p"><span>DEF</span> <span>' + def + '</span></div>' +
      '<div class="sp-pill sta-p"><span>STA</span> <span>' + sta + '</span></div>';
  }

  /* --- Canvas Radar --- */
  var canvas = context.element.querySelector('#sp-canvas');
  if (canvas && canvas.getContext) {
    var ctx = canvas.getContext('2d');
    var W = 140, H = 140, cx = 70, cy = 72, R = 44;
    var axes = [
      { label: 'ATK', val: atk, max: 370, angle: -Math.PI / 2, color: '#ff8800' },
      { label: 'DEF', val: def, max: 340, angle: Math.PI / 6, color: '#4488ff' },
      { label: 'STA', val: sta, max: 500, angle: 5 * Math.PI / 6, color: '#44cc44' }
    ];

    function pt(r, a) {
      return { x: cx + r * Math.cos(a), y: cy + r * Math.sin(a) };
    }

    ctx.clearRect(0, 0, W, H);

    // Redes concéntricas
    for (var lv = 1; lv <= 4; lv++) {
      ctx.beginPath();
      var rr = R * lv / 4;
      ctx.moveTo(pt(rr, axes[0].angle).x, pt(rr, axes[0].angle).y);
      for (var ai = 1; ai < axes.length; ai++) {
        var p = pt(rr, axes[ai].angle);
        ctx.lineTo(p.x, p.y);
      }
      ctx.closePath();
      ctx.strokeStyle = 'rgba(255, 255, 255, ' + (0.05 + lv * 0.03) + ')';
      ctx.lineWidth = 0.8;
      ctx.stroke();
    }

    // Ejes radiales
    axes.forEach(function (a) {
      var p = pt(R, a.angle);
      ctx.beginPath();
      ctx.moveTo(cx, cy);
      ctx.lineTo(p.x, p.y);
      ctx.strokeStyle = 'rgba(255, 255, 255, 0.15)';
      ctx.lineWidth = 1;
      ctx.stroke();
    });

    // Polígono de poder
    ctx.beginPath();
    axes.forEach(function (a, i) {
      var r = R * Math.min(a.val / a.max, 1);
      var p = pt(r, a.angle);
      if (i === 0) ctx.moveTo(p.x, p.y); else ctx.lineTo(p.x, p.y);
    });
    ctx.closePath();
    ctx.fillStyle = 'rgba(255, 165, 0, 0.25)';
    ctx.fill();
    ctx.strokeStyle = '#ffcb05';
    ctx.lineWidth = 1.8;
    ctx.stroke();

    // Nodos y etiquetas de texto
    axes.forEach(function (a) {
      var r = R * Math.min(a.val / a.max, 1);
      var p = pt(r, a.angle);

      ctx.beginPath();
      ctx.arc(p.x, p.y, 3.5, 0, 2 * Math.PI);
      ctx.fillStyle = a.color;
      ctx.fill();
      ctx.strokeStyle = '#fff';
      ctx.lineWidth = 1;
      ctx.stroke();

      var lp = pt(R + 14, a.angle);
      ctx.font = 'bold 9px "Courier New", monospace';
      ctx.fillStyle = a.color;
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      ctx.fillText(a.label, lp.x, lp.y - 4);

      ctx.font = '8px "Courier New", monospace';
      ctx.fillStyle = '#ffe066';
      ctx.fillText(a.val, lp.x, lp.y + 6);
    });
  }

  /* --- Attacks List --- */
  var el = context.element.querySelector('.sp-moves');
  if (!el) return;
  if (!attacks || !attacks.length) {
    el.innerHTML = '<div class="sp-nd">Sin movimientos superefectivos (>= 1.6x)</div>';
    return;
  }

  var html = '';
  for (var i = 0; i < attacks.length; i++) {
    var a = attacks[i];
    var dps = a.avg_dps ? parseFloat(a.avg_dps).toFixed(1) : '—';
    var bars = a.barras ? '▊'.repeat(Math.min(parseInt(a.barras), 3)) : '';
    var efec = a.efectividad ? 'x' + parseFloat(a.efectividad).toFixed(2) : '';

    html += '<div class="atk-card"><div class="atk-rk">#' + (i + 1) + '</div>';
    html += '<div class="atk-mv">';

    // Fila del Ataque Rápido
    html += '<div class="mv">' +
      '<span class="mv-t t-' + a.tipoR + '">' + a.tipoR + '</span>' +
      '<span class="mv-n">' + a.rapido + '</span>' +
      '<span class="mv-d">⚡' + a.dmgR + '</span>' +
      (a.stabR ? '<span class="stab">STAB</span>' : '') +
      '</div>';

    // Fila del Ataque Cargado (con indicador de efectividad)
    html += '<div class="mv">' +
      '<span class="mv-t t-' + a.tipoC + '">' + a.tipoC + '</span>' +
      '<span class="mv-n">' + a.cargado + '</span>' +
      '<span class="mv-d">💥' + a.dmgC + '</span>' +
      (bars ? '<span class="enb">' + bars + '</span>' : '') +
      (a.stabC ? '<span class="stab">STAB</span>' : '') +
      (efec ? '<span class="efec-badge">' + efec + '</span>' : '') +
      '</div>';

    html += '</div><div class="atk-dps">' + dps + '<br><span class="dps-l">DPS</span></div></div>';
  }
  el.innerHTML = html;
})();

