.mini-fill { height: 100% !important; background-color: #ffcb05 !important; }
.highlighting .mini-fill { background-color: #eab308 !important; }
.highlighting-max .mini-fill { background-color: #10b981 !important; }

/* --- SECCIÓN 2: COMPONENTE GRAFICO --- */
.poke-chart-list {
  display: flex !important;
  flex-direction: column !important;
  gap: 10px !important;
}

.baya-group-box {
  display: flex !important;
  flex-direction: column !important;
  background: linear-gradient(135deg, #1e293b, #0f172a, #334155) !important;
  border: 1px solid rgba(255, 255, 255, 0.05) !important;
  border-radius: 8px !important;
  padding: 10px 14px !important;
  box-shadow: inset 0 0 8px rgba(0, 0, 0, 0.6) !important;
}

.baya-group-header { margin-bottom: 6px !important; }

.chart-row-item {
  display: flex !important;
  align-items: center !important;
  gap: 12px !important;
  margin-bottom: 6px !important;
}

.chart-row-item:last-child { margin-bottom: 0 !important; }

.row-info-label {
  font-size: 11px !important; /* Letra grande */
  font-weight: 800 !important;
  color: #9ca3af !important;
  width: 65px !important;
  text-transform: uppercase !important;
}

.row-info-label.curve-label { color: #3b82f6 !important; }

.bar-gauge-track {
  flex-grow: 1 !important;
  height: 12px !important;
  background-color: rgba(255, 255, 255, 0.04) !important;
  border-radius: 9999px !important;
  position: relative !important;
  overflow: hidden !important;
}

.bar-gauge-fill {
  height: 100% !important;
  border-radius: 9999px !important;
  transition: width 0.8s ease-in-out !important;
  box-shadow: inset 0 1.5px 2px rgba(255, 255, 255, 0.2) !important;
}

.rate-max-value {
  font-size: 12px !important; /* Letra grande */
  font-weight: 900 !important;
  color: #ffffff !important;
  min-width: 55px !important;
  text-align: right !important;
}

.highlighting-txt { color: #10b981 !important; }

.rate-low { background-color: #6b7280 !important; }
.rate-mid { background-color: #f59e0b !important; }
.rate-high { background-color: #facc15 !important; }
.rate-god { background-color: #10b981 !important; }

.catch-table-wrapper::-webkit-scrollbar { height: 4px !important; }
.catch-table-wrapper::-webkit-scrollbar-thumb { background: rgba(254, 203, 5, 0.2) !important; border-radius: 10px !important; }

/* --- RESPONSIVIDAD INTEGRADA --- */
@media (max-width: 820px) {
  .analysis-split-layout {
    flex-direction: column !important;
    gap: 18px !important;
  }
  .analysis-layout-divider {
    display: none !important;
  }
}
